const tokenHeader = headers['x-webhook-token'] || headers['X-Webhook-Token'] || '';
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const expectedSecret = 'LumiereWebhookSecret2026!';

let isAuthorized = false;
if (tokenHeader === expectedSecret) {
  isAuthorized = true;
} else if (typeof authHeader === 'string' && authHeader.startsWith('Bearer ') && authHeader.slice(7).trim() === expectedSecret) {
  isAuthorized = true;
}

return {
  json: {
    is_authorized: isAuthorized,
    raw_body: $input.item.json.body || {},
    headers: headers
  }
};

