const raw = $input.item.json.raw_body || {};

let alert = null;
let status = raw.status || raw.state || 'firing';

if (Array.isArray(raw.alerts) && raw.alerts.length > 0) {
  alert = raw.alerts.find(a => (a.status || 'firing') === 'firing') || raw.alerts[0];
} else if (raw.alertname || (raw.labels && raw.labels.alertname)) {
  alert = raw;
} else if (raw.title && (raw.state || raw.message)) {
  alert = {
    labels: { alertname: raw.title, severity: 'warning' },
    annotations: { summary: raw.title, description: raw.message || raw.title }
  };
}

if (!alert) {
  return {
    json: {
      is_valid: false,
      error_message: "Estructura de payload inválida: no se encontró ninguna alerta válida o el array 'alerts' está vacío."
    }
  };
}

const labels = alert.labels || {};
const annotations = alert.annotations || {};

const alertname = labels.alertname || raw.commonLabels?.alertname || raw.groupLabels?.alertname || alert.alertname || raw.title || 'Alerta-Sin-Nombre';
const severity = (labels.severity || raw.commonLabels?.severity || 'warning').toLowerCase();
const instance = labels.instance || labels.host || 'infraestructura-lumiere';
const job = labels.job || 'lumiere-monitoring';
const areaLabel = labels.area || labels.categoria || '';
const summary = annotations.summary || raw.commonAnnotations?.summary || alert.summary || raw.title || alertname;
const description = annotations.description || raw.commonAnnotations?.description || alert.description || raw.message || 'Sin descripción detallada disponible.';
const startsAt = alert.startsAt || new Date().toISOString();

let categoryId = 4;
let categoryName = 'Alertas Automáticas (Prometheus / n8n)';

const textToAnalyze = `${alertname} ${summary} ${description} ${job} ${areaLabel}`.toLowerCase();

if (areaLabel.toLowerCase().includes('seguridad') || /owasp|trivy|token|jwt|auth|security|vulnerab|unauthorized|ataque|pass/i.test(textToAnalyze)) {
  categoryId = 1;
  categoryName = 'Seguridad Informática y Vulnerabilidades';
} else if (areaLabel.toLowerCase().includes('rendimiento') || /postgres|database|db|latency|latencia|query|lenta|wal|replic|replica|sql|pool/i.test(textToAnalyze)) {
  categoryId = 2;
  categoryName = 'Rendimiento y Base de Datos';
} else if (areaLabel.toLowerCase().includes('infraestructura') || /container|contenedor|docker|cadvisor|node|cpu|memoria|memory|disco|disk|tunnel|cloudflare|host|red|down|fail/i.test(textToAnalyze)) {
  categoryId = 3;
  categoryName = 'Infraestructura, Red y Contenedores';
}

let urgency = 3;
let impact = 3;
let priority = 3;

if (severity === 'critical' || severity === 'fatal') {
  urgency = 5;
  impact = 5;
  priority = 5;
} else if (severity === 'warning' || severity === 'high') {
  urgency = 4;
  impact = 4;
  priority = 4;
} else if (severity === 'medium') {
  urgency = 3;
  impact = 3;
  priority = 3;
} else {
  urgency = 2;
  impact = 2;
  priority = 2;
}

const ticketName = `[PROMETHEUS] ${alertname} - ${summary.slice(0, 80)}`;
const ticketContent = `&lt;h3&gt;Alerta Automática de Infraestructura - Joyería Lumière&lt;/h3&gt;` +
  `&lt;p&gt;&lt;strong&gt;Alerta:&lt;/strong&gt; ${alertname}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Severidad:&lt;/strong&gt; ${severity.toUpperCase()}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Instancia / Host:&lt;/strong&gt; ${instance}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Origen / Job:&lt;/strong&gt; ${job}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Fecha y Hora de Detección:&lt;/strong&gt; ${startsAt}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Área Asignada (ITIL):&lt;/strong&gt; ${categoryName}&lt;/p&gt;` +
  `&lt;hr/&gt;` +
  `&lt;p&gt;&lt;strong&gt;Resumen:&lt;/strong&gt; ${summary}&lt;/p&gt;` +
  `&lt;p&gt;&lt;strong&gt;Detalle Técnico:&lt;/strong&gt;&lt;br/&gt;&lt;pre&gt;${description}&lt;/pre&gt;&lt;/p&gt;` +
  `&lt;hr/&gt;` +
  `&lt;p&gt;&lt;small&gt;Ticket generado automáticamente por el flujo n8n (JOY-30). Responsable técnico asignado: Marcos Chambi (SRE).&lt;/small&gt;&lt;/p&gt;`;

return {
  json: {
    is_valid: true,
    alertname,
    severity,
    instance,
    job,
    summary,
    description,
    startsAt,
    category_id: categoryId,
    category_name: categoryName,
    urgency,
    impact,
    priority,
    assigned_user_id: 7,
    ticket_name: ticketName,
    ticket_content: ticketContent
  }
};

