  `• *Área ITIL:* ${alertData.category_name}\n` +
  `• *Instancia:* ${alertData.instance}\n` +
  `• *Resumen:* ${alertData.summary}\n` +
  `• *Detalle:* ${alertData.description}\n` +
  `• *Enlace GLPI:* ${glpiTicketUrl}\n` +
  `• *Fecha/Hora:* ${new Date().toISOString()}`;

return {
