let alertData = { alertname: 'Desconocida', severity: 'warning', instance: 'infraestructura-lumiere', summary: 'Falla en servicio GLPI' };
try {
  const candidate = $('Validar y Procesar Alerta').item.json;
  if (candidate && candidate.alertname) alertData = candidate;
} catch (e) {}

const alertname = alertData.alertname || 'Alerta No Identificada';
const severity = (alertData.severity || 'warning').toUpperCase();
const instance = alertData.instance || 'infraestructura-lumiere';
const summary = alertData.summary || 'Falla en el pipeline de gestión de incidentes';
const errorMsg = $json.error || $json.message || $json || 'Servicio GLPI no disponible o error en API REST';

const emergencyMessage = `🚨 *FALLO CRÍTICO DE GESTIÓN DE INCIDENTES* 🚨\n\n` +
  `⚠️ *NO SE PUDO CREAR EL TICKET EN GLPI*\n` +
  `• *Alerta:* ${alertname}\n` +
  `• *Severidad:* ${severity}\n` +
  `• *Instancia:* ${instance}\n` +
  `• *Resumen:* ${summary}\n` +
  `• *Causa de la Falla:* Servicio GLPI inaccesible o credenciales rechazadas\n` +
  `• *Detalle Error:* ${JSON.stringify(errorMsg)}\n` +
  `• *Acción Requerida:* Atender el incidente manualmente y verificar contenedor lumiere-glpi.`;

return {
  json: {
    emergency: true,
    alertname,
    severity,
    error_detail: errorMsg,
    message_text: emergencyMessage
  }
};

